@SuppressWarnings("unchecked")
protected MachineTimeSlot getFurthestAvailableTimeSlotFrom(
    Machine machine,
    LocalDateTime startDateT,
    LocalDateTime endDateT,
    OperationOrder operationOrder,
    long initialDuration,
    boolean ignoreConcurrency,
    int loopNb)
    throws AxelorException {

  EventsPlanning planning = machine.getPublicHolidayEventsPlanning();

  if (planning != null
      && planning.getEventsPlanningLineList() != null
      && planning.getEventsPlanningLineList().stream()
          .anyMatch(epl -> epl.getDate().equals(endDateT.toLocalDate()))) {

    // If endDate is not available because of planning
    // Then we try for the previous day
    LocalDateTime previousDayDateT = endDateT.plusDays(1).with(LocalTime.MIN);

    return getFurthestAvailableTimeSlotFrom(
        machine,
        previousDayDateT.minusSeconds(initialDuration),
        previousDayDateT,
        operationOrder,
        initialDuration,
        ignoreConcurrency,
        loopNb);
  }

  LocalDateTime plannedStartDateT = null;
  LocalDateTime plannedEndDateT = null;

  if (machine.getWeeklyPlanning() != null) {
    // Planning on date at endDateT
    DayPlanning dayPlanning =
        findDayPlanningOrClosed(machine.getWeeklyPlanning(), endDateT.toLocalDate());
    Optional<LocalDateTime> allowedEndDateTPeriodAt =
        dayPlanningService.getAllowedEndDateTPeriodAt(dayPlanning, endDateT);

    if (allowedEndDateTPeriodAt.isEmpty()) {
      throw new AxelorException(
          TraceBackRepository.CATEGORY_CONFIGURATION_ERROR,
          I18n.get(ProductionExceptionMessage.OPERATION_ORDER_NO_PERIOD_FOUND_FOR_PLAN_DATES),
          operationOrder.getName());
    }

    plannedEndDateT = allowedEndDateTPeriodAt.get();
    plannedStartDateT = plannedEndDateT.minusSeconds(initialDuration);

    // Must start in an existing period. The start date may have jumped onto a
    // different calendar day than endDateT, so its DayPlanning must be looked
    // up again instead of reusing the one resolved for endDateT.
    plannedStartDateT =
        dayPlanningService
            .getAllowedEndDateTPeriodAt(
                findDayPlanningOrClosed(
                    machine.getWeeklyPlanning(), plannedStartDateT.toLocalDate()),
                plannedStartDateT)
            .get();
    // Void duration is time when machine is not used (not in any period)

    long remainingTime = 0l;
    int counter = 0;
    do {

      long voidDuration =
          dayPlanningService.computeVoidDurationBetween(
              dayPlanning, plannedStartDateT, plannedEndDateT);

      remainingTime =
          initialDuration
              - DurationHelper.getSecondsDuration(
                  Duration.between(plannedStartDateT, plannedEndDateT)
                      .minusSeconds(voidDuration));
      // So the time 'spent' must be reported
      plannedStartDateT = plannedStartDateT.minusSeconds(remainingTime);

      // And of course it must start also in an existing period, resolved for its own day.
      plannedStartDateT =
          dayPlanningService
              .getAllowedEndDateTPeriodAt(
                  findDayPlanningOrClosed(
                      machine.getWeeklyPlanning(), plannedStartDateT.toLocalDate()),
                  plannedStartDateT)
              .get();

      counter++;
    } while (remainingTime > 0 && counter < MAX_LOOP_CALL);

    if (counter == MAX_LOOP_CALL) {
      throw new AxelorException(
          TraceBackRepository.CATEGORY_INCONSISTENCY,
          ProductionExceptionMessage.TOO_MANY_CALL_GETTING_START_DATE);
    }

  } else {
    // The machine does not have weekly planning so dates are ok for now.
    plannedStartDateT = startDateT;
    plannedEndDateT = endDateT;
  }

  if (ignoreConcurrency) {
    return new MachineTimeSlot(plannedStartDateT, plannedEndDateT);
  }
  return getFurthestAvailableMachineTimeSlot(
      machine, operationOrder, initialDuration, plannedStartDateT, plannedEndDateT, loopNb);
}

protected MachineTimeSlot getFurthestAvailableMachineTimeSlot(
    Machine machine,
    OperationOrder operationOrder,
    long initialDuration,
    LocalDateTime plannedStartDateT,
    LocalDateTime plannedEndDateT,
    int loopNb)
    throws AxelorException {

  if (loopNb >= MAX_RECURSIVE_CALL) {
    throw new AxelorException(
        TraceBackRepository.CATEGORY_INCONSISTENCY,
        ProductionExceptionMessage.TOO_MANY_CALL_GETTING_TIME_SLOT,
        operationOrder.getName());
  }
  long timeBeforeNextOperation =
      Optional.ofNullable(operationOrder.getWorkCenter())
          .map(WorkCenter::getTimeBeforeNextOperation)
          .orElse(0l);
  // Must check if dates are occupied by other operation orders
  // The first one of the list will be the first to start
  List<OperationOrder> concurrentOperationOrders =
      operationOrderRepository
          .all()
          .filter(
              "self.machine = :machine"
                  + " AND ((self.plannedStartDateT <= :startDate AND self.plannedEndDateT > :startDateWithTime)"
                  + " OR (self.plannedStartDateT < :endDate AND self.plannedEndDateT > :endDateWithTime)"
                  + " OR (self.plannedStartDateT >= :startDate AND self.plannedEndDateT <= :endDateWithTime))"
                  + " AND (self.manufOrder.statusSelect != :cancelled AND self.manufOrder.statusSelect != :finished)"
                  + " AND self.id != :operationOrderId"
                  + " AND self.outsourcing = false")
          .bind("startDate", plannedStartDateT)
          .bind("endDate", plannedEndDateT)
          .bind("startDateWithTime", plannedStartDateT.minusSeconds(timeBeforeNextOperation))
          .bind("endDateWithTime", plannedEndDateT.minusSeconds(timeBeforeNextOperation))
          .bind("machine", machine)
          .bind("cancelled", ManufOrderRepository.STATUS_CANCELED)
          .bind("finished", ManufOrderRepository.STATUS_FINISHED)
          .bind("operationOrderId", operationOrder.getId())
          .order("plannedStartDateT")
          .fetch();

  if (concurrentOperationOrders.isEmpty()) {
    return new MachineTimeSlot(plannedStartDateT, plannedEndDateT);
  } else {
    OperationOrder firstOperationOrder = concurrentOperationOrders.get(0);

    // Can not compute next slot with concurrency if these values are 0
    if (timeBeforeNextOperation == 0 && initialDuration == 0) {
      throw new AxelorException(
          TraceBackRepository.CATEGORY_INCONSISTENCY,
          I18n.get(
              ProductionExceptionMessage.MANUF_ORDER_CANT_COMPUTE_NEXT_SLOT_WITH_CURRENT_CONFIG),
          operationOrder.getName());
    }

    return getFurthestAvailableTimeSlotFrom(
        machine,
        firstOperationOrder
            .getPlannedStartDateT()
            .minusSeconds(initialDuration + timeBeforeNextOperation),
        firstOperationOrder.getPlannedStartDateT().minusSeconds(timeBeforeNextOperation),
        operationOrder,
        initialDuration,
        false,
        loopNb + 1);
  }
}

def validate_duplicate_operating_component(self):
	components = []
	for row in self.workstation_costs:
		if row.operating_component not in components:
			components.append(row.operating_component)
		else:
			frappe.throw(
				_("Duplicate Operating Component {0} found in Operating Components").format(
					bold(row.operating_component)
				)
			)

def before_save(self):
	if self.has_value_changed("workstation_type"):
		self._set_data_based_on_workstation_type()

	self.set_hour_rate()
	self.set_total_working_hours()
	self.disabled_workstation()

def disabled_workstation(self):
	if self.disabled:
		self.status = "Off"

def set_total_working_hours(self):
	self.total_working_hours = 0.0
	for row in self.working_hours:
		self.validate_working_hours(row)

		if row.start_time and row.end_time:
			row.hours = flt(time_diff_in_hours(row.end_time, row.start_time), row.precision("hours"))
			if row.enabled:
				self.total_working_hours += row.hours

def validate_working_hours(self, row):
	if get_time(row.start_time) >= get_time(row.end_time):
		frappe.throw(_("Row #{0}: Start Time must be before End Time").format(row.idx))

def set_hour_rate(self):
	self.hour_rate = 0.0
	for row in self.workstation_costs:
		if row.operating_cost:
			self.hour_rate += flt(row.operating_cost)

def set_data_based_on_workstation_type(self):
	self.check_permission("write")
	self._set_data_based_on_workstation_type()

def _set_data_based_on_workstation_type(self):
	if self.workstation_type:
		data = frappe.get_all(
			"Workstation Cost",
			fields=["operating_component", "operating_cost", "idx"],
			filters={"parent": self.workstation_type, "parenttype": "Workstation Type"},
			order_by="idx",
		)

		if data:
			self.workstation_costs = []

		for row in data:
			self.append(
				"workstation_costs",
				{
					"operating_component": row.operating_component,
					"operating_cost": row.operating_cost,
					"idx": row.idx,
				},
			)

def on_update(self):
	self.validate_overlap_for_operation_timings()
	self.update_bom_operation()

def validate_overlap_for_operation_timings(self):
	"""Check if there is no overlap in setting Workstation Operating Hours"""
	for d in self.get("working_hours"):
		if not d.enabled:
			continue

		wh = frappe.qb.DocType("Workstation Working Hour")
		existing = (
			frappe.qb.from_(wh)
			.select(wh.idx)
			.where(
				(wh.parent == self.name)
				& (wh.name != d.name)
				& (wh.enabled == 1)
				& (wh.start_time < d.end_time)
				& (wh.end_time > d.start_time)
			)
			.run(pluck=True)
		)

		if existing:
			frappe.throw(
				_("Row #{0}: Timings conflicts with row {1}").format(d.idx, comma_and(existing)),
				OverlapError,
			)

def update_bom_operation(self):
	bom_list = frappe.db.sql(
		"""select DISTINCT parent from `tabBOM Operation`
		where workstation = %s and parenttype = 'routing' """,
		self.name,
	)

	for bom_no in bom_list:
		frappe.db.sql(
			"""update `tabBOM Operation`
			set hour_rate = %s, operating_cost = %s * time_in_mins / 60
			where parent = %s and workstation = %s""",
			(self.hour_rate, self.hour_rate, bom_no[0], self.name),
		)

def validate_workstation_holiday(self, schedule_date, skip_holiday_list_check=False):
	if not skip_holiday_list_check and (
		not self.holiday_list
		or cint(frappe.db.get_single_value("Manufacturing Settings", "allow_production_on_holidays"))
	):
		return schedule_date

	if schedule_date in tuple(get_holidays(self.holiday_list)):
		schedule_date = add_days(schedule_date, 1)
		return self.validate_workstation_holiday(schedule_date, skip_holiday_list_check=True)

	return schedule_date

def get_open_job_card(self, job_card, ptype):
	doc = frappe.get_doc("Job Card", job_card)
	doc.check_permission(ptype)

	if doc.docstatus != 0:
		frappe.throw(_("Job Card {0} is not open").format(get_link_to_form("Job Card", doc.name)))

	if doc.workstation != self.name:
		frappe.throw(
			_("Job Card {0} is not for workstation {1}").format(
				get_link_to_form("Job Card", doc.name), frappe.bold(self.name)
			)
		)

	return doc

